    #[test]
    fn incomplete_multiple_unknown_and_extra_field_outputs_are_rejected() {
        let (_root, request, _) = fixture();
        let valid = response("review_cut", serde_json::to_value(accepted()).unwrap());
        assert_eq!(
            parse(&valid, &request).unwrap().verdict,
            ReviewVerdict::Accept
        );
        let mut incomplete = valid.clone();
        incomplete["status"] = json!("incomplete");
        assert!(parse(&incomplete, &request).is_err());
        let mut multiple = valid.clone();
        multiple["output"]
            .as_array_mut()
            .unwrap()
            .push(valid["output"][0].clone());
        assert!(parse(&multiple, &request).is_err());
        let mut unknown = serde_json::to_value(accepted()).unwrap();
        unknown["verdict"] = json!("approve");
        assert!(parse(&response("review_cut", unknown), &request).is_err());
        let mut extra = serde_json::to_value(accepted()).unwrap();
        extra["path"] = json!("/secret");
        assert!(parse(&response("review_cut", extra), &request).is_err());
    }

    #[test]
    fn revision_evidence_never_promotes_preview_or_unsent_frames_to_source_samples() {
        let (_root, request, _) = fixture();
        validate_decision(&request, &revised()).unwrap();
        for id in ["preview-1-500", "source-1-999", "invented"] {
            let mut bad = revised();
            bad.revised_clips[0].evidence_ids = vec![id.into()];
            assert!(validate_decision(&request, &bad).is_err());
        }
        let mut boundary = revised();
        boundary.revised_clips[0].start_ms = 500;
        boundary.revised_clips[0].end_ms = 600;
        validate_decision(&request, &boundary).unwrap();
        boundary.revised_clips[0].start_ms = 0;
        boundary.revised_clips[0].end_ms = 500;
        assert!(
            validate_decision(&request, &boundary).is_err(),
            "half-open end excludes the evidence"
        );
        let mut overlap = revised();
        overlap.revised_clips.push(overlap.revised_clips[0].clone());
        assert!(validate_decision(&request, &overlap).is_err());
    }

    #[test]
    fn issue_and_verdict_limits_reject_ambiguous_or_unbound_decisions() {
        let (_root, request, _) = fixture();
        for variant in 0..8 {
            let mut bad = revised();
            match variant {
                0 => bad.issues[0].kind = "execute_shell".into(),
                1 => bad.issues[0].clip_id = "unknown-clip".into(),
                2 => bad.issues[0].evidence_ids = vec!["unsent-frame".into()],
                3 => {
                    let duplicate = bad.issues[0].evidence_ids[0].clone();
                    bad.issues[0].evidence_ids.push(duplicate);
                }
                4 => bad.summary = "x".repeat(4001),
                5 => bad.issues[0].detail = "x".repeat(2001),
                6 => bad.issues = vec![bad.issues[0].clone(); 13],
                _ => bad.verdict = ReviewVerdict::Uncertain,
            }
            assert!(
                validate_decision(&request, &bad).is_err(),
                "variant {variant}"
            );
        }
        let mut warning_request = request.clone();
        warning_request.quality.objective_pass = false;
        validate_decision(&warning_request, &accepted()).unwrap();
    }

    #[test]
    fn rejected_schema_retains_actual_usage_model_response_and_modality_trace() {
        let (_root, request, provider) = fixture();
        let response = response(
            "shell",
            json!({"untrusted":"do not echo this secret-looking argument"}),
        );
        let record = provider
            .response_record(
                &response,
                &request.call_id,
                PROMPT_VERSION,
                record_sample_ids(&request),
                Some("req_fixture".into()),
                42,
            )
            .unwrap();
        let error = outcome(&request, &response, record).unwrap_err();
        let AgentError::ModelResponseRejected { message, record } = error else {
            panic!("Expected usage-preserving rejection")
        };
        assert!(!message.contains("secret-looking"));
        assert_eq!(
            (record.input_tokens, record.output_tokens, record.elapsed_ms),
            (123, 34, 42)
        );
        assert_eq!(record.requested_model, "gpt-6-luna");
        assert_eq!(record.model, "gpt-6-luna-actual-test-snapshot");
        assert_eq!(
            record.provider_response_id.as_deref(),
            Some("resp_review_fixture")
        );
        assert_eq!(record.request_id.as_deref(), Some("req_fixture"));
        assert_eq!(record.status, "feedback_response_rejected");
        assert!(record.decision.is_none());
        assert_eq!(
            record.sample_ids,
            vec!["source:source-1-500", "preview:preview-1-500"]
        );
        let expected = (123.0 * 0.125 + 34.0 * 0.50) / 1_000_000.0;
        assert!((record.estimated_cost_usd - expected).abs() < 1e-12);
    }

    #[test]
    fn completed_review_record_never_becomes_a_vision_plan_or_human_approval() {
        let (_root, request, provider) = fixture();
        let response = response("review_cut", serde_json::to_value(accepted()).unwrap());
        let record = provider
            .response_record(
                &response,
                &request.call_id,
                PROMPT_VERSION,
                record_sample_ids(&request),
                None,
                1,
            )
            .unwrap();
        let result = outcome(&request, &response, record).unwrap();
        assert_eq!(result.record.status, "feedback_completed");
        assert!(result.record.decision.is_none());
        assert_eq!(result.decision.verdict, ReviewVerdict::Accept);
    }

